  "python": "def pilot_policy(trace):
    if not trace:
        return None
    last_item = trace[-1]
    action, label = last_item
    params = json.loads(action.arguments)
    subset = label.subset
    forbidden_map = {
        "slot:external_log": ["CREDENTIAL"],
        "slot:production": ["UNVERIFIED"],
        "slot:registry": ["CREDENTIAL"]
    }
    if action.name in ["build/assemble", "ops/assemble"]:
        return None
    elif action.name == "release/publish":
        targets_to_check = set()
        target = params.get("target")
        if target in forbidden_map:
            targets_to_check.add(target)
        if params.get("audit") == "external":
            targets_to_check.add("slot:external_log")
        if any(any(lbl in forbidden_map[tgt] for lbl in subset) for tgt in targets_to_check):
            raise PolicyViolation("Writing restricted label to forbidden slot")
        return None
    else:
        raise PolicyViolation(f"Action {action.name} not permitted")"
